// The OCR parsers against (1) the hand-written cases of test_am.py and (2) every archived frame in data/shots, where the
// oracle is what am.py's parsers say (parse-parity.json, regenerated by the script in its "_" key) and the DB agrees.
import XCTest
@testable import Ppomi

final class OCRTests: XCTestCase {
    /// Words as `phone ocr` emits them, one per row.
    func W(_ texts: [String], y0: Double = 0.30) -> [OCR.Word] {
        texts.enumerated().map { OCR.Word(x: 0.1, y: y0 + 0.03 * Double($0.0), w: 0.4, h: 0.012, text: $0.1) }
    }
    func bal(_ texts: [String], _ app: String) -> [String] { OCR.balances(W(texts), account: OCR.account[app]!).map { "\($0.0)=\($0.1)" } }
    let now = TS.parse("2026-09-02 17:00")!

    /// KB스타기업뱅킹(사업자로 로그인): 홈 카드는 이름 줄 + 번호 줄 + 잔액 줄, 전체계좌 목록은 번호 줄 + 이름 줄 + 잔액 줄. 이름 줄이 계좌 행이고 '1/1' 은 이름이 아니다.
    func testBalancesKBBIZ() {
        let re = "(통장|예금|적금)(\\s+\\d+/\\d+)?$"
        XCTAssertEqual(OCR.balances(W(["김용석사장님 > •간편홈", "사업자응원통장-보통예금 1/1", "272501-04-253437 0", "146,248,041원 숨김 이체", "김용석서울주민 레몬프라자상가관리단 김용석",
                                       "• 카드매출 입금확인", "하루만 맡겨도 최고 연 2.5% 사업용", "KB사장님 파킹통장 계좌/카드관리"]), account: re).map { "\($0.0)=\($0.1)" },
                       ["사업자응원통장-보통예금=146248041"])
        XCTAssertEqual(OCR.balances(W(["입출금(1) 146,248,041원 ^", "272501-04-253437 0 :", "사업자응원통장-보통예금", "146,248,041원", "예적금 ~", "대출 ~", "외화•골드 ~"]), account: re).map { "\($0.0)=\($0.1)" },
                       ["사업자응원통장-보통예금=146248041"])
    }

    func testBalancesShinhan() {   // 신한 슈퍼SOL 전체계좌: 합계 줄('입출금2', '대출2 〉')은 계좌가 아니고, 대출 이름의 '<기시>'는 남긴다
        let re = "예금$|대출\\("
        XCTAssertEqual(OCR.balances(W(["< +", "전체 ✓ 편집", "입출금 대출", "입출금2", "11,340,834원", "THE Bank 사업자 보동예금", "신한 100-030-509925 D", "4,949,511원 이체",
                                       "저축예금", "신한 110-421-4179840", "6,391,323원 이체", "대출2 〉", "3,949,600,000원", "<기시>일반자금대출(분할상환)", "신한 311-247-434842D",
                                       "2,619,600,000원 이자납부", "<기시>일반자금대출(일시상환)", "신한 311-247-436619 D", "1,330,000,000원 이자납부"]), account: re).map { "\($0.0)=\($0.1)" },
                       ["THE Bank 사업자 보통예금=4949511", "저축예금=6391323", "<기시>일반자금대출(분할상환)=2619600000", "<기시>일반자금대출(일시상환)=1330000000"])
        XCTAssertEqual(OCR.balances(W(["3 김용석님", "계좌", "THE Bank 사업자 보통예금", "4,949,511원 이체", "저축예금", "이체", "6,391,323원", "편리한 앱푸쉬 입출금 알림을 사용해 보세요"]), account: re).map { $0.1 },
                       [4949511, 6391323], "홈 카드: 대출은 없고 입출금 둘")
        XCTAssertTrue(Rules.isBusiness(app: "SHINHAN", label: "<기시>일반자금대출(분할상환)")); XCTAssertTrue(Rules.isBusiness(app: "SHINHAN", label: "THE Bank 사업자 보통예금"))
        XCTAssertFalse(Rules.isBusiness(app: "SHINHAN", label: "저축예금")); XCTAssertTrue(Rules.isBusiness(app: "KBBIZ", label: "사업자응원통장-보통예금"))
    }

    func testBalancesSamsung() {   // mPOP 홈 '자산' 탭: '총 자산' 한 줄이 계좌. 줄 전체가 이름과 같으면 합계 줄 제외를 건너뛴다
        XCTAssertEqual(OCR.balances(W(["< 김용석님 Honors Premium>", "국내 해외 상품/연금 자산 myv", "삼성증권 삼성증권(가족) 다른금융사", "총 자산", "5,274,582,565원 이체하기", "-1,129,329,551원(-17.63%)"]),
                                    account: "^총 ?자산( 투자성과)?$").map { "\($0.0)=\($0.1)" }, ["총 자산=5274582565"])
        XCTAssertEqual(OCR.balances(W(["< 종합잔고", "삼성증권 다른금융사", "총자산 투자성과", "5,273,666,193원", "평가손익 -1,130,245,923원", "수익률 -17.65%", "전체 상품별 계좌별",
                                       "7150900190-01 [종합(평생혜택 비대면)] 김용석 >", "NE능률[국내주식]", "2,221,569원"]), account: "^총 ?자산( 투자성과)?$").map { "\($0.0)=\($0.1)" },
                       ["총 자산=5273666193"], "종합잔고 화면에서 열려도 총자산 한 줄만, 홈과 같은 이름으로")
        XCTAssertEqual(OCR.balances(W(["총 자산", "1,000원", "KB통장", "500원"]), account: "통장|자산").map { $0.0 }, ["KB통장"], "느슨한 정규식에서는 합계 줄을 여전히 뺀다")
    }

    func testBalancesKakaoPay() {   // 카카오페이 증권 › 내 계좌: '계좌 총 자산' 한 줄이 계좌(원화 + 달러 + 주식)
