    func testKakaoTransactions() {
        let tx = OCR.transactions(["^ AI 관련 지출 통장", "3333-02-1234567 C", "518,574원", "Q 3개월 • 전체 • 최신순 ✓",
                                   "AI 이체의 새로운 방법", "09.02",
                                   "쿠팡이츠 -12,345원", "15:50 #체크카드 518,574원",
                                   "이디야커피 IBK고객 -4,500원", "13:06 #체크카드 530,919원",
                                   "월급 +1,000,000원", "09:00 #입금 535,419원",
                                   "12.31", "GS25 -1,000원", "23:59 #체크카드 100원"], when: now, app: "KAKAO")
        XCTAssertEqual(tx.map { "\($0.ts) \($0.kind) \($0.amount) \($0.merchant) \($0.cumulative)" }, [
            "2026-09-02 15:50 approval 12345 쿠팡이츠 518574", "2026-09-02 13:06 approval 4500 이디야커피 IBK고객 530919",
            "2026-09-02 09:00 deposit 1000000 월급 535419", "2025-12-31 23:59 approval 1000 GS25 100"])   // 12.31 read in September is last year
        XCTAssertEqual(Set(tx.map(\.uid)).count, 4)
        // rows accumulate across scrolled pages: page 2 has no date header and a merchant/time pair straddles the boundary
        let p1 = ["09.02", "가맹점1 -1,000원", "18:00 #체크카드 9,000원", "가맹점2 -1,000원"]
        let p2 = ["17:00 #체크카드 10,000원", "가맹점3 -1,000원", "16:00 #체크카드 11,000원", "09.01 :", "가맹점4 -2,000원", "21:00 #체크카드 13,000원"]
        XCTAssertEqual(OCR.transactions(p1 + p2, when: now, app: "KAKAO").map { "\($0.ts) \($0.merchant)" },
                       ["2026-09-02 18:00 가맹점1", "2026-09-02 17:00 가맹점2", "2026-09-02 16:00 가맹점3", "2026-09-01 21:00 가맹점4"])
        // a scrolled page opens with the rows that sat just above its first date header on the previous page: they keep the newer date
        let q1 = ["09.01", "가맹점A -1,000원", "22:48 #체크카드 64,041원", "08.31", "가맹점B -2,000원", "23:24 #체크카드 979,417원"]
        let q2 = ["가맹점A -1,000원", "22:48 #체크카드 64,041원", "08.31", "가맹점B -2,000원", "23:24 #체크카드 979,417원", "가맹점C -3,000원", "19:06 #체크카드 348,770원"]
        XCTAssertEqual(OCR.transactions([OCR.page] + q1 + [OCR.page] + q2, when: now, app: "KAKAO").map { "\($0.ts) \($0.merchant)" },
                       ["2026-09-01 22:48 가맹점A", "2026-08-31 23:24 가맹점B", "2026-09-01 22:48 가맹점A", "2026-08-31 23:24 가맹점B", "2026-08-31 19:06 가맹점C"])
        // the natural key ignores OCR drift in the merchant text, a tag with a space still parses, '-' with 취소 in the name is spend
        let a = OCR.transactions(["09.02", "이디야커피 IBK고객 -4,500원", "13:06 #체크카드 530,919원"], when: now, app: "KAKAO")[0]
        let b = OCR.transactions(["09.02", "이디야커피 I BK고객 -4,500원", "13:06 # 체크카드 530,919원"], when: now, app: "KAKAO")[0]
        XCTAssertEqual(a.uid, b.uid); XCTAssertEqual(b.card, "체크카드")
        XCTAssertEqual(a.uid, "KAKAO:2026-09-02 13:06:-4500:530919")
        let c1 = OCR.transactions(["09.02", "취소마트 -3,000원", "12:00 #체크카드 1,000원", "쿠팡 +3,000원", "12:30 #체크카드 취소 4,000원"], when: now, app: "KAKAO")
        XCTAssertEqual(c1.map(\.kind), ["approval", "cancel"])
        // deposits carry no sign and (transfers in) no tag; interest has a tag; OCR sometimes reads '-' as '~'
        let d = OCR.transactions(["08.30", "CURSOR USAGE MID AU -155,934원", "22:59 #체크카드 989,222원", "홍길동 1,000,000원", "22:59 1,145,156원",
                                  "입출금통장 이자 40원", "04:29 #예금이자 1,087,310원", "CURSOR USAGE AUG ~152,308원", "14:12 #체크카드 913,102원"], when: now, app: "KAKAO")
        XCTAssertEqual(d.map { "\($0.kind) \($0.amount) \($0.merchant) [\($0.card)] \($0.cumulative)" }, [
            "approval 155934 CURSOR USAGE MID AU [체크카드] 989222", "deposit 1000000 홍길동 [] 1145156",
            "deposit 40 입출금통장 이자 [예금이자] 1087310", "approval 152308 CURSOR USAGE AUG [체크카드] 913102"])
    }

