    // ---------------------------------------------------------------- parity over the archived frames
    static let shots = URL(fileURLWithPath: LedgerTests.dbPath).deletingLastPathComponent().appendingPathComponent("shots")
    static let fixture = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("parse-parity.json")

    func oracle() throws -> [String: Any] {
        guard FileManager.default.fileExists(atPath: Self.shots.path), let d = try? Data(contentsOf: Self.fixture)
        else { throw XCTSkip("no data/shots or parse-parity.json") }
        return try JSONSerialization.jsonObject(with: d) as! [String: Any]
    }
    /// Only the frames the oracle saw: data/shots keeps growing after parse-parity.json was generated.
    func frames() -> [URL] {
        let cut = (try? Self.fixture.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantFuture
        return ((try? FileManager.default.contentsOfDirectory(at: Self.shots, includingPropertiesForKeys: nil)) ?? [])
            .filter { $0.pathExtension == "jsonl" && when($0.lastPathComponent) <= cut }.sorted { $0.lastPathComponent < $1.lastPathComponent }
    }
    func when(_ name: String) -> Date {
        let f = DateFormatter(); f.locale = Locale(identifier: "en_US_POSIX"); f.dateFormat = "yyyyMMdd-HHmmss"
        return f.date(from: String(name.prefix(15)))!
    }

    /// Same runs (list frames grouped by app, <2 min apart) and, per run, the same transactions in the same order as am.py.
    func testTransactionParityWithPython() throws {
        let o = try oracle()
        var found: [(when: Date, app: String, rows: [String], name: String)] = []
        for j in frames() {
            let rows = OCR.rows(OCR.words(jsonl: j))
            for (app, marker) in OCR.listMarkers.sorted(by: { $0.key < $1.key }) where rows.filter({ marker.match($0) != nil }).count >= 2 {
                found.append((when(j.lastPathComponent), app, rows, j.lastPathComponent))
            }
        }
        var runs: [(app: String, frames: [String], tx: [OCR.Tx])] = [], run: [(when: Date, app: String, rows: [String], name: String)] = []
        for f in found.map(Optional.some) + [nil] {
            if !run.isEmpty, f == nil || f!.app != run.last!.app || f!.when.timeIntervalSince(run.last!.when) > 120 {
                let rows = run.flatMap { [OCR.page] + $0.rows }
                runs.append((run[0].app, run.map(\.name), OCR.parse(app: run[0].app, rows: rows, when: run.last!.when)))
                run = []
            }
            if let f { run.append(f) }
        }
        let py = o["runs"] as! [[String: Any]]
        XCTAssertEqual(runs.count, py.count, "run count")
        for (s, p) in zip(runs, py) {
            XCTAssertEqual(s.app, p["app"] as? String); XCTAssertEqual(s.frames, p["frames"] as? [String])
            let want = (p["tx"] as! [[String: Any]]).map { "\($0["uid"]!) \($0["ts"]!) \($0["kind"]!) \($0["amount"]!) \($0["merchant"]!) [\($0["card"]!)] \($0["cumulative"]!)" }
            let got = s.tx.map { "\($0.uid) \($0.ts) \($0.kind) \($0.amount) \($0.merchant) [\($0.card)] \($0.cumulative)" }
            XCTAssertEqual(got, want, "run \(s.frames.first ?? "")")
        }
        // and the DB, which am.py reparse filled from the same frames, holds exactly these uids
        let db = Set((o["db"] as! [[String: Any]]).map { $0["uid"] as! String })
        XCTAssertEqual(Set(runs.flatMap { $0.tx.map(\.uid) }), db)
    }

    /// Every frame, every app's account pattern: the same (label, balance) list as am.py.
    func testBalanceParityWithPython() throws {
        let o = try oracle()
        var want: [String: [String]] = [:]
        for b in o["balances"] as! [[String: Any]] {
            want["\(b["frame"]!)|\(b["app"]!)"] = (b["found"] as! [[Any]]).map { "\($0[0])=\($0[1])" }
        }
        var got: [String: [String]] = [:]
        for j in frames() {
            let words = OCR.words(jsonl: j)
            for (app, re) in OCR.account {
                let r = OCR.balances(words, account: re).map { "\($0.0)=\($0.1)" }
                if !r.isEmpty { got["\(j.lastPathComponent)|\(app)"] = r }
            }
        }
        XCTAssertEqual(got.count, want.count)
        for (k, w) in want { XCTAssertEqual(got[k], w, k) }
    }
}
